@code {
    [Parameter, EditorRequired] public Message? RootMessage { get; set; }
    [Parameter, EditorRequired] public List<Message> Replies { get; set; } = new();
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnReplySubmit { get; set; }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

@page "/chat"
@using sv_e51838cd8c3e45c693eb6ddaa19e8c30.Services
@inject IChatService ChatService
@rendermode InteractiveServer

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <ChannelSidebar Channels="channels"
                    ActiveChannelId="selectedChannel?.Id"
                    OnChannelSelected="SelectChannel" />

    <div class="chat-main @(threadOpen ? "with-thread" : "")">
        <MessageArea ChannelName="@selectedChannel?.Name"
                     ChannelDescription="@selectedChannel?.Description"
                     Messages="messages"
                     ThreadSummaries="threadSummaries"
                     IsLoadingMore="isLoadingMore"
                     OnOpenThread="OpenThread"
                     OnReactionAdded="AddReaction"
                     OnSendMessage="SendMessage"
                     OnLoadOlderMessages="LoadOlderMessages" />
    </div>

    @if (threadOpen && threadRootMessage is not null)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     Replies="threadReplies"
                     OnClose="CloseThread"
                     OnReplySubmit="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> channels = new();
    private List<Message> messages = new();
    private List<ThreadSummary> threadSummaries = new();
    private Channel? selectedChannel;
    private bool isLoadingMore;

    // Thread state
    private bool threadOpen;
    private Message? threadRootMessage;
    private List<Message> threadReplies = new();

    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
    }

    private async Task SelectChannel(Channel channel)
    {
        selectedChannel = channel;
        messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        threadSummaries = GetThreadSummaries(messages);
        await ChatService.MarkChannelReadAsync(channel.Id);

        // Update unread count locally
        var idx = channels.FindIndex(c => c.Id == channel.Id);
        if (idx >= 0)
        {
            channels[idx] = channel with { UnreadCount = 0 };
        }

        CloseThread();
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannel is null) return;
        var msg = await ChatService.SendMessageAsync(selectedChannel.Id, content, null);
        messages.Add(msg);
    }

    private async Task LoadOlderMessages()
    {
        if (selectedChannel is null || isLoadingMore) return;
        isLoadingMore = true;
        var older = await ChatService.GetMessagesAsync(selectedChannel.Id, messages.Count, PageSize);
        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            threadSummaries = GetThreadSummaries(messages);
        }
        isLoadingMore = false;
    }

    private async Task OpenThread(Message message)
    {
        threadRootMessage = message;
        threadReplies = await ChatService.GetThreadAsync(message.Id);
        threadOpen = true;
    }

    private void CloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadReplies = new();
    }

    private async Task SendThreadReply(string content)
    {
        if (selectedChannel is null || threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannel.Id, content, threadRootMessage.Id);
        threadReplies.Add(reply);

        // Update thread summary
        var existing = threadSummaries.FindIndex(t => t.RootMessageId == threadRootMessage.Id);
        var summary = new ThreadSummary(threadRootMessage.Id, threadReplies.Count, reply.SentAt);
        if (existing >= 0)
            threadSummaries[existing] = summary;
        else
            threadSummaries.Add(summary);
    }

    private async Task AddReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to reflect updated reactions
        if (selectedChannel is not null)
        {
            messages = await ChatService.GetMessagesAsync(selectedChannel.Id, 0, messages.Count);
        }
    }

    private static List<ThreadSummary> GetThreadSummaries(List<Message> msgs)
    {
        // Build thread summaries from messages that are replies
        var replies = msgs.Where(m => m.ReplyToId.HasValue).ToList();
        return replies
            .GroupBy(m => m.ReplyToId!.Value)
            .Select(g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)))
            .ToList();
    }
}

